#include <bits/stdc++.h>
using namespace std;

long long max( long long a , long long b ) {
    
    return a > b ? a : b;
}

long long max1( long long a , long long b ) {
    
    return a > b ? a : b;
}

long long max2( long long a , long long b ) {
    
    return a > b ? a : b;
}

long long max3( long long a , long long b ) {
    
    return a > b ? a : b;
}
int main() {
	// your code goes here
    int t;
    cin >> t;
    
    while( t-- ) {
        
        int n;
        cin >> n;
        
        vector<long long> ar( 3 * n );
        for( int i = 0; i < n * 3; i++ ) cin >> ar[i];
        
        sort( ar.rbegin() , ar.rend() );
        
        vector<long long> pref( n * 3 + 1 , 0 );
        
        for( int i = 0; i < n * 3; i++ ) 
            pref[i + 1] = pref[i] + ar[i];
        
        long long ans = 0;
        
        for( int i = 0; i <= n; i++ ) {
            
            int l = 0 , r = n - i;
            
            auto v = [&]( int m ) {
                int j = i + 2 * m , k = ( n * 3 ) - 2 * i - m;
                
                return 2 * pref[i] + pref[j] + 3 * pref[k];
                
            };
            
            while( l < r ) {
                
                int b = ( l + r ) / 2;
                
                int j = i + 2 * b , k = ( n * 3 ) - 2 * i - b;
                
                
                long long d = ( pref[j+2] - pref[j] ) + 3 * ( pref[k - 1] - pref[k] );
                
                if( d >= 0 ) l = b + 1;
                else r = b;
            }
            
            ans = max( ans , v(l) );
            
            if( l > 0 ) 
                ans = max( ans , v( l - 1 ) );
        }
        
        cout << ans << endl;
    }
}
